/** Restricts value to the inclusive range [min, max]. Throws if min > max. */
export function clamp(value: number, min: number, max: number): number {
  if (min > max) throw new RangeError(`min (${min}) must not exceed max (${max})`);
  return Math.min(Math.max(value, min), max);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { clamp } from '../src/clamp.ts';

test('returns value when inside the range', () => {
  assert.equal(clamp(5, 0, 10), 5);
});

test('clamps to min and max', () => {
  assert.equal(clamp(-1, 0, 10), 0);
  assert.equal(clamp(11, 0, 10), 10);
});

test('bounds are inclusive', () => {
  assert.equal(clamp(0, 0, 10), 0);
  assert.equal(clamp(10, 0, 10), 10);
  assert.equal(clamp(3, 3, 3), 3);
});

test('throws when min exceeds max', () => {
  assert.throws(() => clamp(1, 10, 0), RangeError);
});

